from django.test import TestCase, override_settings

from .scientific_engine import DeepContentSniffer


def sniff(text: str, filename: str = "input.txt") -> str:
    fmt, err = DeepContentSniffer.sniff_format(text.encode("utf-8"), filename)
    assert err is None, err
    return fmt


class FormatSniffingRegressionTests(TestCase):
    """Regressions for format detection bugs found in the October 2026 audit."""

    def test_orca_input_with_hash_comments_is_not_gaussian(self):
        text = (
            "# Generated by iLoveChem Studio\n"
            "# Electron count: 42 | Parity verified\n"
            "! B3LYP def2-SVP opt freq D3BJ\n"
            "%maxcore 2048\n%pal nprocs 8 end\n\n"
            "* xyz 0 1\n  C  0.0  0.0  0.0\n  H  0.0  0.0  1.09\n*"
        )
        self.assertEqual(sniff(text, "calculation.inp"), "inp")

    def test_gaussian_input_still_detected(self):
        text = "%nprocshared=8\n%mem=16GB\n#p B3LYP/def2-SVP opt freq\n\nTitle\n\n0 1\nC 0 0 0\n"
        self.assertEqual(sniff(text, "mol.gjf"), "gjf")
        self.assertEqual(sniff("# B3LYP/6-31G* opt\n\nTitle\n\n0 1\nC 0 0 0\n", "mol.com"), "gjf")

    def test_xyz_with_hash_comment_is_xyz(self):
        text = "3\n# opt water geometry\nO 0 0 0\nH 0 0 1\nH 0 1 0\n"
        self.assertEqual(sniff(text, "water.xyz"), "xyz")

    def test_pdb_text_with_branched_is_not_pdbqt(self):
        text = (
            "HEADER    TRANSFERASE\nCOMPND   2 MOLECULE: BRANCHED GLYCAN ROOTED\n"
            "ATOM      1  N   ALA A   1      10.000  10.000  10.000  1.00 20.00           N\n"
        )
        self.assertEqual(sniff(text, "x.pdb"), "pdb")

    def test_real_pdbqt_is_pdbqt(self):
        text = "REMARK  1\nROOT\nATOM      1  C   LIG A   1       0.000   0.000   0.000  0.00  0.00    +0.000 C\nENDROOT\nTORSDOF 0\n"
        self.assertEqual(sniff(text, "lig.pdbqt"), "pdbqt")

    def test_smiles_with_lowercase_heteroatoms(self):
        self.assertEqual(sniff("c1ccsc1", "input.xyz"), "smi")   # thiophene
        self.assertEqual(sniff("c1ccoc1", "input.xyz"), "smi")   # furan
        self.assertEqual(sniff("[Fe]", "input.xyz"), "smi")

    def test_organometallic_and_orca_inp_handling(self):
        # Ferrocene with aromatic cyclopentadienyl anions
        self.assertEqual(sniff("[Fe+2].[c-]1cccc1.[c-]1cccc1", "uploaded.txt"), "smi")
        # Direct conversion test of ORCA inp
        orca_inp = (
            "# Generated by iLoveChem Studio\n"
            "! B3LYP def2-SVP opt freq\n"
            "* xyz 0 1\n"
            "  C  0.0  0.0  0.0\n"
            "  H  0.0  0.0  1.09\n"
            "*\n"
        )
        self.assertEqual(sniff(orca_inp, "calc.inp"), "inp")
        from .converter_core import parse_and_extract_atoms
        mol, meta = parse_and_extract_atoms(orca_inp.encode('utf-8'), "inp")
        self.assertIsNotNone(mol)
        self.assertEqual(meta["parsed_by"], "ORCA Input Coordinate Extractor")
        self.assertEqual(len(mol.atoms), 2)

    def test_pdbqt_gasteiger_charges_and_organometallic_properties(self):
        from openbabel import pybel
        from .converter_core import export_to_target_format
        from .chem_utils import calculate_properties, validate_smiles, generate_3d_molblock

        # 1. PDBQT Gasteiger Partial Charge Verification
        m = pybel.readstring("smi", "CC(=O)O")
        m.make3D()
        pdbqt_str, _, _ = export_to_target_format(m, "pdbqt")
        atom_lines = [l for l in pdbqt_str.splitlines() if l.startswith("ATOM") or l.startswith("HETATM")]
        self.assertGreater(len(atom_lines), 0)
        has_nonzero_charge = any(abs(float(l[70:76].strip())) > 0.001 for l in atom_lines)
        self.assertTrue(has_nonzero_charge, "PDBQT exporter must assign non-zero Gasteiger partial charges")

        # 2. Organometallic Ferrocene Cheminformatics Verification
        fc_smi = "[Fe+2].[c-]1cccc1.[c-]1cccc1"
        self.assertTrue(validate_smiles(fc_smi))
        props = calculate_properties(fc_smi)
        self.assertNotIn("error", props)
        self.assertGreater(props.get("molecular_weight", 0), 150.0)
        res_3d = generate_3d_molblock(fc_smi)
        self.assertIn("mol_block", res_3d)


class SiteMetadataTests(TestCase):
    @override_settings(SITE_URL="https://example.org", ALLOWED_HOSTS=["evil.example"])
    def test_sitemap_uses_configured_https_origin_and_lists_about(self):
        body = self.client.get("/sitemap.xml", HTTP_HOST="evil.example").content.decode()
        self.assertIn("https://example.org/about/", body)
        self.assertNotIn("evil.example", body)
        self.assertNotIn("http://", body.replace("http://www.sitemaps.org", ""))

    @override_settings(SITE_URL="https://example.org")
    def test_robots_points_to_configured_sitemap(self):
        body = self.client.get("/robots.txt").content.decode()
        self.assertIn("Sitemap: https://example.org/sitemap.xml", body)

    def test_public_source_bundle_and_history_endpoints_are_gone(self):
        self.assertEqual(self.client.get("/audit/bundle/").status_code, 404)
        self.assertEqual(self.client.get("/api/history/").status_code, 404)



class MolecularDockingEngineTests(TestCase):
    def setUp(self):
        self.mock_pdb = (
            "CRYST1   40.000   40.000   40.000  90.00  90.00  90.00 P 1\n"
            "ATOM      1  N   ASP A  25      10.000  10.000  10.000  1.00 20.00           N\n"
            "ATOM      2  CA  ASP A  25      11.000  10.000  10.000  1.00 20.00           C\n"
            "ATOM      3  C   ASP A  25      11.500  11.400  10.000  1.00 20.00           C\n"
            "ATOM      4  O   ASP A  25      10.800  12.300  10.000  1.00 20.00           O\n"
            "ATOM      5  CB  ASP A  25      11.700   9.000   9.000  1.00 20.00           C\n"
            "ATOM      6  CG  ASP A  25      11.200   7.600   9.200  1.00 20.00           C\n"
            "ATOM      7  OD1 ASP A  25      10.000   7.400   9.500  1.00 20.00           O\n"
            "ATOM      8  OD2 ASP A  25      12.000   6.700   9.000  1.00 20.00           O\n"
            "HETATM   20  C1  DRG A 100      11.000   7.500  12.000  1.00 15.00           C\n"
            "HETATM   21  C2  DRG A 100      12.200   7.500  12.000  1.00 15.00           C\n"
            "HETATM   22  O1  DRG A 100      10.500   6.400  11.500  1.00 15.00           O\n"
            "HETATM   23  N1  DRG A 100      13.000   8.500  12.500  1.00 15.00           N\n"
            "HETATM   24  C3  DRG A 100      14.200   8.500  12.500  1.00 15.00           C\n"
            "HETATM   25  C4  DRG A 100      15.000   9.600  13.000  1.00 15.00           C\n"
            "HETATM   26  O2  DRG A 100      14.500  10.800  13.000  1.00 15.00           O\n"
            "HETATM   30  O   HOH A 201      25.000  25.000  25.000  1.00 18.00           O\n"
            "END\n"
        )

    def test_centroid_sniffer_and_pocket_bounding_box(self):
        from .docking_core import DockingEngine
        info = DockingEngine.detect_co_crystallized_ligand_and_centroid(self.mock_pdb)
        self.assertTrue(info["has_co_crystal_ligand"])
        self.assertEqual(info["ligand_resname"], "DRG")
        self.assertAlmostEqual(info["center_x"], 12.914, delta=0.5)
        self.assertGreaterEqual(info["size_x"], 18.0)

    def test_rigid_receptor_preparation_and_torsion_tree_ligand(self):
        from .docking_core import DockingEngine
        rec_pdbqt, meta = DockingEngine.prepare_receptor_pdbqt(self.mock_pdb)
        self.assertNotIn("DRG", rec_pdbqt)
        self.assertNotIn("HOH", rec_pdbqt)
        self.assertNotIn("ROOT", rec_pdbqt)
        self.assertNotIn("TORSDOF", rec_pdbqt)

        lig_pdbqt, lig_meta = DockingEngine.prepare_ligand_pdbqt("CC(=O)Oc1ccccc1C(=O)O")
        self.assertIn("ROOT", lig_pdbqt)
        self.assertIn("ENDROOT", lig_pdbqt)
        self.assertIn("TORSDOF", lig_pdbqt)

    def test_inbuilt_chemdock_execution_pipeline(self):
        from .docking_core import ChemDockEngine
        rec_pdbqt, _ = ChemDockEngine.prepare_receptor_pdbqt(self.mock_pdb)
        lig_pdbqt, _ = ChemDockEngine.prepare_ligand_pdbqt("CC(=O)Oc1ccccc1C(=O)O")
        res = ChemDockEngine.run_docking(
            receptor_pdbqt=rec_pdbqt,
            ligand_pdbqt=lig_pdbqt,
            center_x=12.914,
            center_y=8.4,
            center_z=12.357,
            size_x=16.0,
            size_y=16.0,
            size_z=16.0,
            exhaustiveness=2,
            num_modes=3
        )
        self.assertTrue(res["success"])
        self.assertIn("ChemDock", res["engine"])
        self.assertGreater(res["poses_count"], 0)
        self.assertIsNotNone(res["best_affinity_kcal_mol"])

    def test_docking_studio_view_renders(self):
        resp = self.client.get('/docking/')
        self.assertEqual(resp.status_code, 200)
        self.assertContains(resp, "Molecular Docking Studio")
        self.assertContains(resp, "3Dmol.js")

    def test_api_fetch_rcsb_pdb_validation(self):
        resp = self.client.get('/api/dock/fetch-pdb/INVALID_TOO_LONG/')
        self.assertEqual(resp.status_code, 400)
        self.assertFalse(resp.json()["success"])

    def test_api_run_docking_validation(self):
        # Missing receptor
        resp = self.client.post('/api/dock/run/', {}, content_type="application/json")
        self.assertEqual(resp.status_code, 400)
        self.assertIn("error", resp.json())

        # Missing ligand
        resp = self.client.post('/api/dock/run/', {"receptor_pdb": self.mock_pdb}, content_type="application/json")
        self.assertEqual(resp.status_code, 400)
        self.assertIn("error", resp.json())

    def test_api_run_docking_success(self):
        payload = {
            "receptor_pdb": self.mock_pdb,
            "ligand_input": "CC(=O)Oc1ccccc1C(=O)O",
            "ligand_format": "smiles",
            "center_x": 12.9,
            "center_y": 8.4,
            "center_z": 12.3,
            "size_x": 16.0,
            "size_y": 16.0,
            "size_z": 16.0,
            "exhaustiveness": 2,
            "num_modes": 3
        }
        resp = self.client.post('/api/dock/run/', payload, content_type="application/json")
        self.assertEqual(resp.status_code, 200)
        data = resp.json()
        self.assertTrue(data["success"])
        self.assertGreater(data["num_poses"], 0)
        self.assertIsNotNone(data["best_affinity_kcal_mol"])
        self.assertIn("consolidated_complex_pdb", data)
        self.assertIn("HETATM", data["consolidated_complex_pdb"])
        self.assertIn("interaction_diagram_svg", data)
        self.assertIn("<svg", data["interaction_diagram_svg"])
        self.assertIn("interaction_diagram_svg_white", data)
        self.assertIn("pymol_macro_script", data)
        self.assertIn("show cartoon", data["pymol_macro_script"])
        self.assertIn("pocket_residues", data)
        self.assertIn("hbond_contacts", data)
        self.assertIn("interaction_diagram_svg", data["poses"][0])

    def test_2d_interaction_svg_and_pymol_script(self):
        from .interaction_diagram import generate_2d_interaction_svg, generate_pymol_script
        hb = [{
            'receptor_residue': 'ASP 25:A',
            'resn': 'ASP',
            'resi': 25,
            'chain': 'A',
            'distance_angstrom': 2.74,
            'ligand_atom_idx': 2
        }]
        hp = [{
            'receptor_residue': 'ILE 50:A',
            'resn': 'ILE',
            'resi': 50,
            'chain': 'A',
            'distance_angstrom': 3.65,
            'ligand_atom_idx': 4
        }]
        sb = [{
            'receptor_residue': 'ARG 8:A',
            'resn': 'ARG',
            'resi': 8,
            'chain': 'A',
            'distance_angstrom': 3.12,
            'ligand_atom_idx': 1
        }]
        svg_dark = generate_2d_interaction_svg('CC(=O)Oc1ccccc1C(=O)O', hb, hp, sb, theme='dark')
        self.assertIn('<svg', svg_dark)
        self.assertIn('ASP 25:A', svg_dark)
        self.assertIn('2.74Å', svg_dark)
        self.assertIn('ILE 50:A', svg_dark)
        self.assertIn('± ionic', svg_dark)

        svg_white = generate_2d_interaction_svg('CC(=O)Oc1ccccc1C(=O)O', hb, hp, sb, theme='white')
        self.assertIn('fill="#FFFFFF"', svg_white)

        pml = generate_pymol_script('docked_complex.pdb')
        self.assertIn('load docked_complex.pdb', pml)
        self.assertIn('show cartoon, receptor', pml)
        self.assertIn('set cartoon_transparency, 0.4', pml)
        self.assertIn('distance hbonds, ligand, pocket, 3.5', pml)
